def is_geometric(seq):
    """Check if a sequence is a geometric progression.
    A sequence is GP if for all consecutive triples: a[i-1]^2 = a[i-2] * a[i]"""
    n = len(seq)
    if n <= 2:
        return True

    if all(x == 0 for x in seq):
        return True

    # For longer sequences, check the GP property using cross-multiplication
    for i in range(2, n):
        if seq[i-1] * seq[i-1] != seq[i-2] * seq[i]:
            return False

    return True

