def is_valid_axis_aligned(grid, r, c, size, n, m):
    """Check if there's a valid axis-aligned square with border of 1s."""
    border_cells = set()
    center_cell = None

    # Collect all border and interior cells
    for i in range(size):
        for j in range(size):
            border_cells.add((r + i, c + j))
            if i > 0 and i < size - 1 and j > 0 and j < size - 1:
                center_cell = (r + i, c + j)

    # All border cells must be '1'
    for br, bc in border_cells:
        if grid[br][bc] != '1':
            return False

    # All interior cells must be '0' (not '1')
