        if grid[center_cell[0]][center_cell[1]] == '1':
            return False

    return True

def is_valid_rotated(grid, r, c, size, n, m):
    """Check if there's a valid rotated (diamond) square."""
    # Center of the rotated square
    center_r = r + (size - 1) // 2
    center_c = c + (size - 1) // 2

    half = size // 2

    # Border cells have Manhattan distance exactly half from center
    border_cells = set()
    for i in range(size):
        for j in range(size):
            dist = abs(i - center_r) + abs(j - center_c)
            if dist == half:
                border_cells.add((r + i, c + j))

    # All border cells must be '1'
    for br, bc in border_cells:
        if grid[br][bc] != '1':
            return False

    # Interior cells have Manhattan distance < half from center
    # interior border cells (touching the inside) must be '0'
    for i in range(size):
        for j in range(size):
            dist = abs(i - center_r) + abs(j - center_c)
            if dist < half:
                if grid[r + i][c + j] == '1':
                    return False

    return True

