    # Stable Roommates Algorithm
    lines = input_str.strip().split('\n')
    if not lines:
        return '-1\n'

    try:
        n = int(lines[0])
    except ValueError:
        return '-1\n'

    # Return -1 for odd number of cities (can't perfectly pair)
    if n % 2 != 0:
        return '-1\n'

    # Parse cost matrix with diagonal skipped
    costs = [[0] * n for _ in range(n)]
    for i in range(len(lines)):
        if i == 0:
            continue
        raw_line = lines[i]
        if not raw_line.strip():
            continue
        values = list(map(int, raw_line.split()))
        for j in range(n):
            if j != i:
                costs[i][j] = values[j if j < i else j]

    # Build preference lists (lower cost = higher priority)
    preferences = []
    for i in range(n):
        prefs = []
        for j in range(n):
            if i != j:
                c = costs[i][j]
                prefs.append((j + 1, c))  # 1-indexed
        prefs.sort(key=lambda x: x[1])
        preferences.append([x[0] for x in prefs])

    # Initialize matching: each city matched to none (0)
    matching = [0] * (n + 1)  # 1-indexed, matching[i] = partner of city i

    # Try Irving-I algorithm for stable roommates
    improved = True
    while improved:
        improved = False
        inserted = [False] * (n + 1)

        # Process cities in order, letting them propose
        for u in range(1, n + 1):
            if inserted[u]:
                continue

            # Try to insert u into or create matching with best available
            for v in preferences[u]:
                if matching[v] == 0:
                    # v is free, match with u
                    matching[u] = v
                    matching[v] = u
                    inserted[u] = True
                    inserted[v] = True
                    improved = True
                    break
                else:
                    # v matched with someone, check if v prefers u
                    current_partner = matching[v]
                    if preferences[v].index(u) < preferences[v].index(current_partner):
                        # v prefers u over current partner
                        matching[u] = v
                        matching[v] = u
                        # Current partner of v is now free
                        matching[current_partner] = 0
                        inserted[current_partner] = inserted[u]
                        inserted[v] = True
                        inserted[current_partner] = True
                        improved = True  # Matching changed
                    if inserted[u]:
                        break

        # Check for blocking pairs
        stable = True
        for u in range(1, n + 1):
            if matching[u] == 0:
                continue
            v = matching[u]

            # Check if u and v are still matched to each other
            if matching[v] != u:
                stable = False
                break

        if not stable:
            # Need more iterations or algorithm adjustment
            improved = True

    # Verify stability: no blocking pairs
    blocking_exists = False
    for u in range(1, n + 1):
        v = matching[u]
        if matching[v] != u or v == 0:
            blocking_exists = True
            break

    # Output result
    if blocking_exists or any(matching[i] == 0 for i in range(1, n + 1)):
        return '-1\n'

    result = []
    for i in range(1, n + 1):
        result.append(str(matching[i]))
    return '\n'.join(result) + '\n'


