        for i in range(1, m + 1):
            u, v, w = map(int, lines[i].split())
            pre_edges.append((u, v, w))
            edge_set.add((u, v))
            edge_set.add((v, u))

        # Kruskal's algorithm
        parent = list(range(n + 1))
        def find(i):
            if parent[i] != i:
                parent[i] = find(parent[i])
            return parent[i]

        def union(i, j):
            pi, pj = find(i), find(j)
            return pi != pj, pi if pi != pj else None, pi if pi != pj else pj

        all_edges = []
        for u, v, w in pre_edges:
            all_edges.append((w, u, v, 1))  # (weight, u, v, type)

        # Add unassigned edges with weight 0
        for i in range(1, n + 1):
            for j in range(i + 1, n + 1):
                if (i, j) not in edge_set:
                    all_edges.append((0, i, j, 0))  # unassigned

        # Sort by weight
        all_edges.sort(key=lambda x: x[0])

        mst_weight = 0
        edges_in_mst = 0
        in_mst_edges = []

        for w, u, v, edge_type in sorted(all_edges):
            union_return, _, _ = union(u, v)
            if union_return:
                mst_weight += w
                edges_in_mst += 1
                in_mst_edges.append((u, v, w, edge_type))

            if edges_in_mst == n - 1:
                break

        # Calculate XOR sum of pre-assigned edges
        pre_xor = 0
        for u, v, w in pre_edges:
            pre_xor ^= w

        # Find unassigned edges not in MST
        def is_in_mst(u, v):
            return (u, v) in [(i, j) for u, v, w, t in in_mst_edges] or \
                   (v, u) in [(i, j) for u, v, w, t in in_mst_edges]

        unassigned_not_in_mst = False
        for i in range(1, n + 1):
            for j in range(i + 1, n + 1):
                if (i, j) not in edge_set:
                    if not is_in_mst(i, j):
                        unassigned_not_in_mst = True
                        break
            if unassigned_not_in_mst:
                break

        if unassigned_not_in_mst:
            return str(mst_weight) + '\n'
        else:
            # All unassigned edges are in MST, must increasing MST weight by pre_xor
            # Minimize by using the smallest possible unassigned edge in MST to adjust
            return str(mst_weight + pre_xor) + '\n'

    return solve()

