def canonical(s):
    """Get the minimum form in the equivalence class of string s"""
    # The 4 possible transformations: original, reverse, invert, reverse+invert
    forms = [s, 
             s[::-1],
             ''.join('1' if c == '0' else '0' for c in s),
             ''.join('1' if c == '0' else '0' for c in s[::-1])]
    return min(forms)

